{"version":3,"file":"index.js","sources":["../../src/preload/index.ts"],"sourcesContent":["import { contextBridge, ipcRenderer } from 'electron'\r\n\r\n// 暴露给渲染进程的 API\r\ncontextBridge.exposeInMainWorld('electronAPI', {\r\n  // 存档\r\n  saveGame: (data: unknown) => ipcRenderer.invoke('save-game', data),\r\n  loadGame: () => ipcRenderer.invoke('load-game'),\r\n  \r\n  // 配置\r\n  getConfig: () => ipcRenderer.invoke('get-config'),\r\n  setConfig: (config: unknown) => ipcRenderer.invoke('set-config', config),\r\n  \r\n  // 菜单事件监听\r\n  onMenuNewGame: (callback: () => void) => {\r\n    ipcRenderer.on('menu:new-game', callback)\r\n    return () => ipcRenderer.removeListener('menu:new-game', callback)\r\n  },\r\n  onMenuSave: (callback: () => void) => {\r\n    ipcRenderer.on('menu:save', callback)\r\n    return () => ipcRenderer.removeListener('menu:save', callback)\r\n  },\r\n  onMenuLoad: (callback: () => void) => {\r\n    ipcRenderer.on('menu:load', callback)\r\n    return () => ipcRenderer.removeListener('menu:load', callback)\r\n  },\r\n})\r\n\r\n// 类型声明\r\ndeclare global {\r\n  interface Window {\r\n    electronAPI: {\r\n      saveGame: (data: unknown) => Promise<{ success: boolean; error?: string }>\r\n      loadGame: () => Promise<{ success: boolean; data?: unknown; error?: string }>\r\n      getConfig: () => Promise<{ musicVolume: number; sfxVolume: number }>\r\n      setConfig: (config: unknown) => Promise<{ success: boolean }>\r\n      onMenuNewGame: (callback: () => void) => () => void\r\n      onMenuSave: (callback: () => void) => () => void\r\n      onMenuLoad: (callback: () => void) => () => void\r\n    }\r\n  }\r\n}\r\n"],"names":[],"mappings":";AAGA,cAAc,kBAAkB,eAAe;AAAA;AAAA,EAE7C,UAAU,CAAC,SAAkB,YAAY,OAAO,aAAa,IAAI;AAAA,EACjE,UAAU,MAAM,YAAY,OAAO,WAAW;AAAA;AAAA,EAG9C,WAAW,MAAM,YAAY,OAAO,YAAY;AAAA,EAChD,WAAW,CAAC,WAAoB,YAAY,OAAO,cAAc,MAAM;AAAA;AAAA,EAGvE,eAAe,CAAC,aAAyB;AACvC,gBAAY,GAAG,iBAAiB,QAAQ;AACxC,WAAO,MAAM,YAAY,eAAe,iBAAiB,QAAQ;AAAA,EACnE;AAAA,EACA,YAAY,CAAC,aAAyB;AACpC,gBAAY,GAAG,aAAa,QAAQ;AACpC,WAAO,MAAM,YAAY,eAAe,aAAa,QAAQ;AAAA,EAC/D;AAAA,EACA,YAAY,CAAC,aAAyB;AACpC,gBAAY,GAAG,aAAa,QAAQ;AACpC,WAAO,MAAM,YAAY,eAAe,aAAa,QAAQ;AAAA,EAC/D;AACF,CAAC;"}A,yBAAY,GAAG,aAAa,QAAQ;AACpC,WAAO,MAAMA,SAAAA,YAAY,eAAe,aAAa,QAAQ;AAAA,EAC/D;AACF,CAAC;"}